import{_ as t,o,c as a,a2 as r}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"Decision record R1 — document generation","description":"Decision record R1 — how Scout generates Word documents. Hand-built OpenXML with a real styles part, not a template library.","frontmatter":{"description":"Decision record R1 — how Scout generates Word documents. Hand-built OpenXML with a real styles part, not a template library."},"headers":[],"relativePath":"design/decisions/report-document-generation.md","filePath":"design/decisions/report-document-generation.md"}'),n={name:"design/decisions/report-document-generation.md"};function i(s,e,d,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="decision-record-r1-—-document-generation" tabindex="-1">Decision record R1 — document generation <a class="header-anchor" href="#decision-record-r1-—-document-generation" aria-label="Permalink to &quot;Decision record R1 — document generation&quot;">​</a></h1><blockquote><p><strong>Status:</strong> Accepted 2026-08-02, retroactively. The choice was made in code first and written down after, which is the wrong order; this record exists so the next person does not re-litigate it from scratch.</p><p><strong>Epic:</strong> AB#6450 · <strong>Feature:</strong> AB#6874/AB#6875 · <strong>Author:</strong> Claude Code</p></blockquote><h2 id="_1-decision" tabindex="-1">1. Decision <a class="header-anchor" href="#_1-decision" aria-label="Permalink to &quot;1. Decision&quot;">​</a></h2><p><strong>Keep hand-built OpenXML. Add the parts that were missing, rather than adopt a template library or a <code>.dotx</code>.</strong></p><p>The plan proposed evaluating PSWriteWord, PSWriteOffice, a branded <code>.dotx</code> the renderer populates, and raw OpenXML. Raw OpenXML wins — but only because the thing that was actually broken was never the assembly method.</p><h2 id="_2-why" tabindex="-1">2. Why <a class="header-anchor" href="#_2-why" aria-label="Permalink to &quot;2. Why&quot;">​</a></h2><p>The diagnosis in the plan said the renderer &quot;hand-assembles OpenXML&quot; as though that were the defect. It was not. Phase 0 measured the real defect: the emitted <code>.docx</code> contained <strong>three package parts</strong> — <code>_rels/.rels</code>, <code>[Content_Types].xml</code>, <code>word/document.xml</code> — and <strong>0 of 1,803 paragraphs carried a <code>pStyle</code></strong>.</p><p>That single absence explains every symptom at once. No styles means no navigation pane, no possible TOC field (a TOC collects heading <em>styles</em>, and there were none), no cross-references, and nothing a partner can restyle. A template library would have supplied those parts as a side effect, which is why swapping the library <em>looks</em> like the fix — but the fix is the parts, and the parts are about 400 lines of well-commented code.</p><p>Against that, each alternative costs something real:</p><table tabindex="0"><thead><tr><th>Option</th><th>Cost</th></tr></thead><tbody><tr><td><strong>PSWriteWord / PSWriteOffice</strong></td><td>A third-party dependency on the critical path of a deliverable, for a wrapper over the same SDK. Scout already pins <code>DocumentFormat.OpenXml</code> and acquires it once into a cache; adding a second layer buys nothing it does not already have.</td></tr><tr><td><strong>A branded <code>.dotx</code> the renderer populates</strong></td><td>Genuinely attractive, and the right answer <em>if</em> a designer authors the template. Without one, the template becomes a binary asset in the repo that nobody can diff, review, or explain — and the styles inside it would be hand-authored anyway. It also makes per-assessment restyling a binary edit.</td></tr><tr><td><strong>Word COM</strong></td><td>Rejected on sight. Windows-only, needs Word installed, no CI.</td></tr></tbody></table><h2 id="_3-what-this-commits-us-to" tabindex="-1">3. What this commits us to <a class="header-anchor" href="#_3-what-this-commits-us-to" aria-label="Permalink to &quot;3. What this commits us to&quot;">​</a></h2><p>The document&#39;s identity lives in <code>Add-ScoutDocxStyleDefinitions</code> and <code>Add-ScoutDocxThemePart</code>, in code, in git. Rebranding is swapping a <code>clrScheme</code> and a font scheme — a reviewable diff rather than a binary swap. The conformance test asserts that <strong>no run in the body carries a hex absent from the theme</strong>, which is what keeps that promise honest: adding a colour to a renderer without adding it to the theme fails the build.</p><h2 id="_4-reconsider-this-if" tabindex="-1">4. Reconsider this if <a class="header-anchor" href="#_4-reconsider-this-if" aria-label="Permalink to &quot;4. Reconsider this if&quot;">​</a></h2><p>A designer produces a real branded template, or a partner needs to ship their own. At that point the <code>.dotx</code> route becomes correct, and the styles part built here is the specification for what that template must declare.</p><h2 id="_5-sources" tabindex="-1">5. Sources <a class="header-anchor" href="#_5-sources" aria-label="Permalink to &quot;5. Sources&quot;">​</a></h2><ul><li><a href="https://github.com/EvotecIT/PSWriteWord" target="_blank" rel="noreferrer">PSWriteWord</a> · <a href="https://petri.com/format-microsoft-word-docs-powershell/" target="_blank" rel="noreferrer">styling Word from PowerShell</a></li><li>ECMA-376 Part 1, §17.3 (<code>CT_PPrBase</code> / <code>CT_RPr</code> child ordering) — the ordering rules that cost the most time here and are commented at every site that depends on them.</li></ul>',16)])])}const u=t(n,[["render",i]]);export{m as __pageData,u as default};
